-- 로컬에서 검토한 음방·직캠·외부 콘텐츠 및 쇼츠 편성을 등록한다.
-- 편성 기준 0: 누락 행만 등록, 1: 기존 탭도 정리, 2: 사용자 지정 탭을 자동 분류에서 보호.
ALTER TABLE media CHANGE COLUMN IF EXISTS curated_external curated_tab BOOLEAN NOT NULL DEFAULT FALSE;

CREATE TEMPORARY TABLE tmp_reviewed_media (
    youtube_id VARCHAR(32) NOT NULL PRIMARY KEY,
    tab VARCHAR(32) NOT NULL,
    title VARCHAR(255) NOT NULL,
    duration VARCHAR(32) NOT NULL,
    views BIGINT NOT NULL,
    published_on DATE NOT NULL,
    artist_names VARCHAR(240) NOT NULL,
    assignment SMALLINT NOT NULL
) DEFAULT CHARSET=utf8mb4;










UPDATE media m
JOIN tmp_reviewed_media reviewed ON BINARY m.youtube_id = BINARY reviewed.youtube_id
SET m.tab = reviewed.tab,
    m.curated_tab = m.curated_tab OR reviewed.assignment = 2,
    m.media_title = IF(TRIM(m.media_title) = '', reviewed.title, m.media_title),
    m.media_dur = IF(TRIM(m.media_dur) IN ('', '0:00'), reviewed.duration, m.media_dur),
    m.view_count = IF(m.view_count = 0, reviewed.views, m.view_count),
    m.published_on = COALESCE(m.published_on, reviewed.published_on)
WHERE reviewed.assignment > 0 AND NOT m.curated_tab;

SELECT reviewed.youtube_id, reviewed.tab, reviewed.title, reviewed.duration, reviewed.views, reviewed.published_on, TRUE
FROM tmp_reviewed_media reviewed
WHERE NOT EXISTS (
    SELECT 1 FROM media m WHERE BINARY LOWER(m.youtube_id) = BINARY LOWER(reviewed.youtube_id)
);

-- 확인한 직캠 멤버를 합치고, 다른 영상은 멤버가 비어 있는 경우에만 채운다.
SELECT m.id, a.artist_id
FROM tmp_reviewed_media reviewed
JOIN media m ON BINARY m.youtube_id = BINARY reviewed.youtube_id
JOIN artist a ON FIND_IN_SET(BINARY a.name, BINARY reviewed.artist_names) > 0
LEFT JOIN media_artist link ON link.media_id = m.id AND link.artist_id = a.artist_id
WHERE link.media_id IS NULL
  AND ((reviewed.tab = 'fancam' AND reviewed.assignment = 2) OR NOT EXISTS (
      SELECT 1 FROM media_artist existing WHERE existing.media_id = m.id
  ));

DROP TEMPORARY TABLE tmp_reviewed_media;

-- 모바일 미리보기에서 제거한 비공식 팬 편집 쇼츠 두 건을 운영 목록에서도 제거한다.
DELETE FROM media WHERE BINARY youtube_id IN ('PR6mJ59QMNc', 'OYx2SGkx6f0');
